class entity;
class ai_goal;
class ai_locomotion;

extern "C" void *memmove(void *, const void *, unsigned int);
void *arch_malloc(unsigned int, const char *, int);
void arch_free(void *);

class entity_interface {
protected:
    entity *my_entity;
public:
    entity_interface(entity *ent) : my_entity(ent) {}
    virtual ~entity_interface() {}
};

template<class T> struct list_node {
    list_node *next;
    list_node *prev;
    T value;
};

template<class T> class list {
    list_node<T> node;
public:
    void push_back(const T& value)
    {
        list_node<T> *n = (list_node<T> *)arch_malloc(sizeof(list_node<T>), "C:/KS/SRC/ai_interface.cpp", 0);
        n->value = value;
        n->next = &node;
        n->prev = node.prev;
        node.prev->next = n;
        node.prev = n;
    }
};

template<class T> class vector {
    T *start;
    T *finish;
    T *end_of_storage;
public:
    vector() : start(0), finish(0), end_of_storage(0) {}
    void reserve(unsigned int n)
    {
        unsigned int count = finish - start;
        if ((unsigned int)(end_of_storage - start) < n) {
            T *p = (T *)arch_malloc(n * sizeof(T), "C:/KS/SRC/ai_interface.cpp", 0);
            memmove(p, start, count * sizeof(T));
            if (end_of_storage - start)
                arch_free(start);
            start = p;
            finish = p + count;
            end_of_storage = p + n;
        }
    }
    void resize(unsigned int n)
    {
        if (n < (unsigned int)(finish - start))
            finish = start + n;
        else
            while ((unsigned int)(finish - start) < n)
                *finish++ = T();
    }
};

class ai_interface : public entity_interface {
protected:
    unsigned int flags;
    unsigned int team;
    unsigned int enemy_team;
    static list<ai_interface *> all_ai_interfaces;
    ai_locomotion *locomotion;
    vector<ai_goal *> goals;
    ai_goal *current_goal;
    entity *target;
    float help_timer;
    int disable_count;
public:
    ai_interface(entity *ent);
    virtual ~ai_interface();
};

ai_interface::ai_interface(entity *ent)
  : entity_interface(ent),
  flags(0),
  team(0),
  enemy_team(0),
  disable_count(0)
{
  locomotion = 0;

  all_ai_interfaces.push_back(this);

  target = 0;

  current_goal = 0;

  help_timer = 0.0f;

  goals.reserve(10);
  goals.resize(0);
}
